"""Golden tests: the package must match fixtures generated by the paper code in the paper's pinned environment
(Python 3.9, pymatgen 2024.2.20; see tests/data/make_golden.py). A failure on newer dependencies signals drift
in an upstream library (e.g. pymatgen's neighbour list or CrystalNN), not a change in ChemSPAR.
Set CHEMSPAR_STRICT_GOLDEN=1 to treat drift as a failure (used by the pinned CI job)."""
import json
import os

import pytest
from golden_lib import POLICY_KEYS, TAUS, fingerprint
from helpers import ALL_CIFS, DATA, cif_id, graph_for

FIXTURES = {p.stem: p for p in (DATA / "golden").glob("*.json")}
PINNED = ("pymatgen", "numpy", "scipy")


def _paper_stack(fx) -> bool:
    """True if pymatgen, numpy and scipy are the versions the fixture was generated with."""
    from importlib.metadata import version
    return all(version(p) == fx["generated_with"][p] for p in PINNED)


def _fixture(path):
    sid = cif_id(path)
    if sid not in FIXTURES:
        pytest.skip(f"no golden fixture for {sid}")
    return json.loads(FIXTURES[sid].read_text())


@pytest.mark.parametrize("path", ALL_CIFS, ids=cif_id)
def test_graph_matches_fixture(path):
    from collections import Counter
    fx = _fixture(path)
    g = graph_for(str(path))
    assert len(g) == fx["n_instances"]
    assert dict(Counter(g.attrs(k)["bond_class"] for k in g.instances)) == fx["bond_class_counts"]


@pytest.mark.parametrize("tau", TAUS)
@pytest.mark.parametrize("policy", POLICY_KEYS)
@pytest.mark.parametrize("path", ALL_CIFS, ids=cif_id)
def test_view_matches_fixture(path, policy, tau):
    from chemspar import prune_policy
    fx = _fixture(path)
    g = graph_for(str(path))
    view, log = prune_policy(g, policy, tau)
    got, want = fingerprint(len(g), view.removed, log.rows, tau), fx["views"][f"{policy}@{tau}"]
    strict = os.environ.get("CHEMSPAR_STRICT_GOLDEN") == "1"
    if got != want and not strict and not _paper_stack(fx):
        pytest.xfail("pymatgen/numpy differ from the paper pins: contact distances can change in the last bit, "
                     "which reorders contacts with tied scores (exact only with paper/requirements.txt)")
    assert got == want


def test_every_cif_has_a_fixture():
    missing = [cif_id(p) for p in ALL_CIFS if cif_id(p) not in FIXTURES]
    assert not missing, f"run tests/data/make_golden.py in the paper environment for: {missing}"
